seq = ""
with open("region.fasta") as f:
    for line in f:
        if line.startswith(">"):
            header = line.strip()
        else:
            seq += line.strip()

from collections import Counter
print("header:", header)
print("length:", len(seq))
print("alphabet:", Counter(seq))
gc = (seq.count("G")+seq.count("C"))/len(seq)
print("GC%%: %.3f" % (gc*100))

def revcomp(s):
    comp = str.maketrans("ACGTacgt","TGCAtgca")
    return s.translate(comp)[::-1]

# ORF finding in all 6 frames, allowing all ATG starts and also any codon->stop
stops = {"TAA","TAG","TGA"}
starts = {"ATG"}
def find_orfs(s, min_len=100):
    orfs = []
    for frame in range(3):
        i = frame
        while i < len(s)-2:
            codon = s[i:i+3]
            if codon in starts:
                j = i
                while j < len(s)-2:
                    c = s[j:j+3]
                    if c in stops:
                        orfs.append((i, j+3, j-i, "+", frame, s[i]) )
                        break
                    j += 3
                else:
                    orfs.append((i, len(s), len(s)-i, "+", frame, s[i]))
            i += 3
    return orfs

orfs_plus = find_orfs(seq)
orfs_minus = find_orfs(revcomp(seq))
long_plus = [o for o in orfs_plus if o[2]>200]
long_minus = [o for o in orfs_minus if o[2]>200]
print("long ORFs >200nt on + strand (start, end, len, frame):")
for o in sorted(long_plus, key=lambda x:-x[2])[:10]:
    print(o)
print("long ORFs >200nt on - strand (start, end, len, frame) coords in revcomp space:")
for o in sorted(long_minus, key=lambda x:-x[2])[:10]:
    o2 = (len(seq)-o[1], len(seq)-o[0], o[2], "-", o[4], o[5])
    print(o, "-> obverse coords:", o2)
